class Order {
  private static final int MAX_ITEMS = 3;
  private final List<String> items = new ArrayList<>();

  public void addItem(String item) {
    if (items.size() >= MAX_ITEMS) {
      throw new IllegalStateException("Too many items");
    }
    items.add(item);
  }

  public List<String> getItems() {
    return items;
  }
}

import java.util.Objects;

public class Main {
  public static void main(String[] args) {
    Point p = new Point(1, 2);
    ColorPoint cp = new ColorPoint(1, 2, "red");
    System.out.println(p.equals(cp) + " " + cp.equals(p));
  }
}

class Point {
  final int x, y;
  Point(int x, int y) { this.x = x; this.y = y; }

  @Override
  public boolean equals(Object o) {
    if (!(o instanceof Point other)) return false;
    return x == other.x && y == other.y;
  }

  @Override
  public int hashCode() { return Objects.hash(x, y); }
}

class ColorPoint extends Point {
  final String color;
  ColorPoint(int x, int y, String color) { super(x, y); this.color = color; }

  @Override
  public boolean equals(Object o) {
    if (!(o instanceof ColorPoint other)) return false;
    return super.equals(other) && color.equals(other.color);
  }
}

