@Service
public class SubscriptionService {
  private final StripeClient stripe =
      new StripeClient(System.getenv("STRIPE_KEY"));

  public Invoice renew(Subscription sub) {
    if (sub.expiresAt().isAfter(LocalDateTime.now())) {
      throw new IllegalStateException("Not expired yet");
    }
    Charge charge = stripe.charge(sub.customerId(), sub.price());
    return Invoice.from(sub, charge);
  }
}
